def analyze_sample(
    args: argparse.Namespace, sample_id: int, out_dir: Path
) -> tuple[dict[str, Any], dict[str, Any]]:
    paths = resolve_inputs(args, sample_id)
    out_dir.mkdir(parents=True, exist_ok=True)
    raw = {key: path.read_bytes() for key, path in paths.items() if path is not None}
    replacement = infer_replacement(raw["gt"], raw["corrupted"], raw["model"])
    metadata = load_metadata(args.metadata, sample_id, args.streams_dir)

    with tempfile.TemporaryDirectory(prefix="fim-repair-") as name:
        temp_dir = Path(name)
        results = {
            "gt_strict": decode_stream(paths["gt"], "gt_strict", True, temp_dir, args.ffmpeg_binary, args.timeout_sec, args.max_frames),
            "corrupted_strict": decode_stream(paths["corrupted"], "corrupted_strict", True, temp_dir, args.ffmpeg_binary, args.timeout_sec, args.max_frames),
            "corrupted_default": decode_stream(paths["corrupted"], "corrupted_default", False, temp_dir, args.ffmpeg_binary, args.timeout_sec, args.max_frames),
            "model_strict": decode_stream(paths["model"], "model_strict", True, temp_dir, args.ffmpeg_binary, args.timeout_sec, args.max_frames),
            "model_default": decode_stream(paths["model"], "model_default", False, temp_dir, args.ffmpeg_binary, args.timeout_sec, args.max_frames),
        }
        frames, diffs, visual = save_assets(results, out_dir)

    generated_span = summarize_generated_span(
        raw["model"], replacement["model_hole_start"], replacement["model_hole_end"]
    )
    model_repair_end = (
        replacement["model_hole_start"] + generated_span["repair_bytes"]
    )
    syntax = {
        "gt": syntax_trace(raw["gt"], replacement["gt_hole_start"], replacement["gt_hole_end"]),
        # Keep the complete trace for frame/MB attribution elsewhere in the UI.
        "model": syntax_trace(raw["model"], replacement["model_hole_start"], replacement["model_hole_end"]),
        # Section 3 compares only bytes that still belong to the damaged frame.
        "model_repair": syntax_trace(
            raw["model"], replacement["model_hole_start"], model_repair_end,
            clip_failures=True,
        ),
        "model_continuation": syntax_trace(
            raw["model"], model_repair_end, replacement["model_hole_end"],
            clip_failures=True,
        ),
        # The evaluator appends this region after generation. Keep it in a
        # separate provenance lane so it can never be mistaken for policy
        # output merely because it is present in the reconstructed stream.
        "observed_suffix": syntax_trace(
            raw["gt"], replacement["gt_hole_end"], len(raw["gt"]),
            clip_failures=True,
        ),
    }
    corruption_targets = identify_corrupted_frames(
        raw["gt"], replacement["gt_hole_start"], replacement["gt_hole_end"]
    )
    reconnection_frame = identify_reconnection_frame(
        raw["model"], replacement["model_hole_end"]
    )
    causal_diagnosis = analyze_first_divergence(
        raw["gt"],
        raw["model"],
        gt_start=replacement["gt_hole_start"],
        gt_end=replacement["gt_hole_end"],
        model_start=replacement["model_hole_start"],
        model_end=model_repair_end,
    )
    target_frame = int(corruption_targets[0]["frame_index"]) if corruption_targets else 0
    model_errors = visual["mb_errors"].get("model_strict", [])
    frame_errors = model_errors[target_frame] if target_frame < len(model_errors) else None
    causal_diagnosis["first_visible_error_mb"] = (
        next(
            (
                mb for mb, error in enumerate(frame_errors)
                if error >= args.artifact_threshold
            ),
            None,
        )
        if frame_errors is not None
        else None
    )
    causal_diagnosis["model_repair_parse_ok"] = bool(syntax["model_repair"]["parse_ok"])
    causal_diagnosis["last_model_repair_mb"] = max(
        (
            int(segment["mb_max"])
            for segment in syntax["model_repair"]["segments"]
            if segment["mb_max"] is not None
        ),
        default=None,
    )
    causal_diagnosis["expected_final_mb"] = int(visual["mb_cols"] * visual["mb_rows"] - 1)
    causal_diagnosis["model_completed_target_frame"] = bool(
        causal_diagnosis["model_repair_parse_ok"]
        and causal_diagnosis["last_model_repair_mb"] is not None
        and causal_diagnosis["last_model_repair_mb"]
        >= causal_diagnosis["expected_final_mb"]
    )
    model_ycbcr_frames = visual["mb_ycbcr"].get("model_strict", [])
    frame_ycbcr = (
        model_ycbcr_frames[target_frame]
        if target_frame < len(model_ycbcr_frames)
        else []
    )
    entry_mb = causal_diagnosis["entry_mb"]
    baseline = None
    first_chroma_drift_mb = None
    strongest_green_mb = None
    if frame_ycbcr and entry_mb is not None:
        baseline_tiles = frame_ycbcr[max(0, entry_mb - 8) : entry_mb]
        if baseline_tiles:
            baseline = {
                "cb": float(np.median([tile["cb"] for tile in baseline_tiles])),
                "cr": float(np.median([tile["cr"] for tile in baseline_tiles])),
            }
            first_chroma_drift_mb = next(
                (
                    mb for mb in range(entry_mb, len(frame_ycbcr))
                    if abs(frame_ycbcr[mb]["cb"] - baseline["cb"])
                    + abs(frame_ycbcr[mb]["cr"] - baseline["cr"])
                    >= 12.0
                ),
                None,
            )
        strongest_green_mb = min(
            range(entry_mb, len(frame_ycbcr)),
            key=lambda mb: frame_ycbcr[mb]["cb"] + frame_ycbcr[mb]["cr"],
        )
    causal_diagnosis["chroma_baseline"] = baseline
    causal_diagnosis["first_chroma_drift_mb"] = first_chroma_drift_mb
    causal_diagnosis["first_chroma_drift_ycbcr"] = (
        frame_ycbcr[first_chroma_drift_mb]
        if first_chroma_drift_mb is not None
        else None
    )
    causal_diagnosis["strongest_green_mb"] = strongest_green_mb
    causal_diagnosis["strongest_green_ycbcr"] = (
        frame_ycbcr[strongest_green_mb] if strongest_green_mb is not None else None
    )
    causal_diagnosis["model_decoder_errors"] = summarize_decoder_errors(
        results["model_strict"].stderr
    )
    report = {
        "sample_id": sample_id,
        "inputs": {key: str(value) if value is not None else None for key, value in paths.items()},
        "metadata": metadata,
        "raw": {key: {"bytes": len(value), "nals": scan_nals(value)} for key, value in raw.items()},
        "replacement": replacement,
        "decodes": {key: asdict(value) for key, value in results.items()},
        "assets": {"frames": frames, "diffs": diffs},
        "visual": visual,
        "syntax": syntax,
        "generated_span": generated_span,
        "corruption_targets": corruption_targets,
        "reconnection_frame": reconnection_frame,
        "causal_diagnosis": causal_diagnosis,
        "artifact_threshold": args.artifact_threshold,
        "stream_scope": (
            "full_window"
            if str(paths["gt"]).endswith("_gt_full.h264")
            else "target_truncated_fallback"
        ),
    }
    safe_report = json_safe(report)
    (out_dir / "report.json").write_text(json.dumps(safe_report, indent=2, allow_nan=False) + "\n")
    (out_dir / "report.html").write_text(render(safe_report))
    summary = {
        "sample_id": sample_id,
        "report": str(out_dir / "report.html"),
        "replacement": replacement,
        "frames": {key: len(value.frame_paths) for key, value in results.items()},
        "syntax_segments": {key: len(value["segments"]) for key, value in syntax.items()},
    }
    return safe_report, summary


def discover_sample_ids(args: argparse.Namespace) -> list[int]:
    if args.streams_dir is None:
        raise SystemExit("--all-samples requires STREAMS_DIR")
    if any((args.gt, args.corrupted, args.model)):
        raise SystemExit("--all-samples cannot be combined with explicit stream paths")
    pattern = re.compile(rf"^sample_(\d+)_({re.escape(args.stop_mode)})_gt\.h264$")
    sample_ids = []
    for path in args.streams_dir.glob(f"sample_*_{args.stop_mode}_gt.h264"):
        match = pattern.match(path.name)
        if match is None:
            continue
        sample_id = int(match.group(1))
        stem = f"sample_{sample_id:04d}_{args.stop_mode}"
        if all(
            (args.streams_dir / f"{stem}_{suffix}.h264").is_file()
            for suffix in ("gt", "corrupted", "model")
        ):
            sample_ids.append(sample_id)
    sample_ids = sorted(set(sample_ids))
    if args.max_samples > 0:
        sample_ids = sample_ids[: args.max_samples]
    if not sample_ids:
        raise SystemExit(f"no complete {args.stop_mode!r} sample triplets found in {args.streams_dir}")
    return sample_ids


def catalog_entry(report: dict[str, Any], stop_mode: str) -> dict[str, Any]:
    sample_id = int(report["sample_id"])
    targets = report.get("corruption_targets", [])
    frame_types = "/".join(dict.fromkeys(str(item["picture_type"]) for item in targets)) or "unknown"
    removed = int(report["replacement"]["gt_removed_bytes"])
    generated_span = report["generated_span"]
    repair = int(generated_span["repair_bytes"])
    continuation = int(generated_span["continuation_bytes"])
    return {
        "sample_id": sample_id,
        "href": f"../sample_{sample_id:04d}_{stop_mode}/report.html",
        "label": (
            f"{sample_id:04d} · {frame_types}-frame · {removed} B removed → "
            f"{repair} B repair + {continuation} B extra"
        ),
    }


def main() -> None:
    args = parse_args()
    if not args.all_samples:
        report, summary = analyze_sample(args, args.sample_id, args.out_dir)
        print(json.dumps(summary, indent=2))
        return

    args.out_dir.mkdir(parents=True, exist_ok=True)
    reports: list[tuple[Path, dict[str, Any]]] = []
    summaries = []
    sample_ids = discover_sample_ids(args)
    for position, sample_id in enumerate(sample_ids, start=1):
        sample_dir = args.out_dir / f"sample_{sample_id:04d}_{args.stop_mode}"
        print(f"[{position}/{len(sample_ids)}] analyzing sample {sample_id:04d}", flush=True)
        report, summary = analyze_sample(args, sample_id, sample_dir)
        reports.append((sample_dir, report))
        summaries.append(summary)

    catalog = [catalog_entry(report, args.stop_mode) for _, report in reports]
    for sample_dir, report in reports:
        (sample_dir / "report.html").write_text(render(report, catalog))
    first_href = catalog[0]["href"].removeprefix("../")
    index_html = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8">'
        f'<meta http-equiv="refresh" content="0; url={html.escape(first_href)}">'
        '<title>FIM repair samples</title></head><body>'
        f'<p><a href="{html.escape(first_href)}">Open sample browser</a></p></body></html>'
    )
    (args.out_dir / "index.html").write_text(index_html)
    print(json.dumps({
        "sample_browser": str(args.out_dir / "index.html"),
        "samples": len(reports),
        "sample_ids": sample_ids,
    }, indent=2))


if __name__ == "__main__":
    main()
